head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > M > setDisabledPanel]<br/>파라미터로 지정한 ID 에 해당하는 패널의 비활성화(disabled)를 설정합니다.",
    "validation" : [
        "파라미터로 지정한 ID 에 해당하는 패널의 비활성화(disabled)를 설정합니다.",
        "id(필수) 비활성화(disabled)를 설정하려는 패널의 디자인 ID 를 설정합니다.",
        "disabled(선택) 패널의 비활성화(disabled) 여부를 true/false 로 설정합니다.",
        "disabled(선택) 파라미터를 생략하면 기본값(true)으로 동작하여 패널이 비활성화됩니다.",
        "패널이 열린 상태에서 true 를 설정하면 해당 패널이 닫힌 후 비활성화 처리됩니다.",
        "패널이 닫힌 상태에서 false 를 설정 시 패널이 자동으로 열리지는 않습니다.",
        "비활성화된 패널은 클릭, openPanel(), closePanel() 메소드에 의한 열기/닫기가 모두 차단됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // collapsible=true, unCollapseAll=true 로 모든 패널이 초기에 열린 상태 환경 보장
    // → 열린 패널에 setDisabledPanel(id, true) 호출 시 닫힌 후 비활성화되는 동작 검증 가능
    let properties = {
        collapsible : "true",
        unCollapseAll : "true",
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onpanelunload"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* setDisabledPanel(par_id, par_disabled) 호출 → par_id 패널의 비활성화 상태가 par_disabled 값으로 설정됨"', '', 'label1');
    $c.gcm.createLabel('label="* par_disabled 생략(빈값) → 기본값 true 적용 → 패널 비활성화"', '', 'label2');
    $c.gcm.createLabel('label="* 열린 패널에 true 설정 → 패널이 닫힌 후 비활성화 (onpanelunload 발생)"', '', 'label3');
    $c.gcm.createLabel('label="* 닫힌 패널에 false 설정 → 비활성화만 해제되고 자동으로 열리지는 않음"', '', 'label4');
    $c.gcm.createLabel('label="* 비활성화된 패널은 openPanel() / closePanel() 메소드 호출이 모두 차단됨"', '', 'label5');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// onpanelunload 핸들러 — 열린 패널에 setDisabledPanel(id, true) 호출 시 패널이 닫힌 후 발생
scwin.target1_onpanelunload = function (panelID, userID) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onpanelunload 이벤트 발생]");
};



// setDisabledPanel(par_id, par_disabled) — par_disabled 빈값이면 인자 생략 (기본값 true 적용)
scwin.btn_setDisabledPanel_onclick = function (e) {
    let panelId = par_id.getValue();
    let disabledVal = par_disabled.getValue();
    if (disabledVal === "" || disabledVal === null) {
        wf_body_bottom.getObj("scwin").setReturnValue("===== setDisabledPanel('" + panelId + "') 호출 (disabled 생략 → 기본값 true) =====");
        target1.setDisabledPanel(panelId);
    } else {
        let disabledBool = (disabledVal === "true");
        wf_body_bottom.getObj("scwin").setReturnValue("===== setDisabledPanel('" + panelId + "', " + disabledBool + ") 호출 =====");
        target1.setDisabledPanel(panelId, disabledBool);
    }

    // 호출 후 각 패널의 활성화/비활성화 상태 출력 (런타임 갱신은 childControlList[i].options.disabledPanels 에 반영됨)
    for (let i = 0; i < target1.childControlList.length; i++) {
        let userID = target1.panelInfoArr[i].userID;
        let disabled = target1.childControlList[i].options.disabledPanels;
        wf_body_bottom.getObj("scwin").setReturnValue("[" + userID + "] disabledPanels = " + disabled);
    }
};



// openPanel(par_id) — 비활성화된 패널에 호출 시 열리지 않아야 함 (차단 확인)
scwin.btn_openPanel_onclick = function (e) {
    let panelId = par_id.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("===== openPanel('" + panelId + "') 호출 =====");
    target1.openPanel(panelId);
};



// closePanel(par_id) — 비활성화된 패널에 호출 시 닫히지 않아야 함 (차단 확인)
scwin.btn_closePanel_onclick = function (e) {
    let panelId = par_id.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("===== closePanel('" + panelId + "') 호출 =====");
    target1.closePanel(panelId);
};



// 열린 패널 확인 — getOpenPanelListInfo 결과 출력
scwin.btn_getOpenPanel_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 결과 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 수 : " + (openList ? openList.length : 0));
    if (openList && openList.length > 0) {
        for (let i = 0; i < openList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("열린 패널[" + i + "] id : " + openList[i].id);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음");
    }
};
